<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(18, 25, 46, 0.88);
      --panel-border: rgba(148, 163, 184, 0.2);
      --text: #f8fafc;
      --muted: #94a3b8;
      --input: #111827;
      --input-border: #334155;
      --accent: #7c3aed;
      --accent-light: #a78bfa;
      --focus: rgba(124, 58, 237, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.32), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.22), transparent 30rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .support-card {
      width: min(100%, 520px);
      padding: 36px;
      border: 1px solid var(--panel-border);
      border-radius: 28px;
      background: linear-gradient(145deg, rgba(30, 41, 59, 0.92), var(--panel));
      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent-light);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 3rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 16px 0 30px;
      color: var(--muted);
      line-height: 1.65;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      color: #dbeafe;
      font-size: 0.95rem;
      font-weight: 650;
    }

    input {
      width: 100%;
      border: 1px solid var(--input-border);
      border-radius: 16px;
      background: rgba(15, 23, 42, 0.94);
      color: var(--text);
      font: inherit;
      padding: 15px 16px;
      outline: none;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: var(--accent-light);
      background: var(--input);
      box-shadow: 0 0 0 4px var(--focus);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.86rem;
      line-height: 1.45;
    }

    button {
      margin-top: 8px;
      border: 0;
      border-radius: 16px;
      background: linear-gradient(135deg, var(--accent), #2563eb);
      color: white;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      padding: 16px 18px;
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.28);
      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
      box-shadow: 0 18px 36px rgba(37, 99, 235, 0.34);
    }

    button:focus-visible {
      outline: 3px solid var(--accent-light);
      outline-offset: 3px;
    }

    @media (max-width: 560px) {
      .support-card {
        padding: 28px 22px;
        border-radius: 22px;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const fields = [
      {
        id: "full-name",
        name: "fullName",
        label: "Full name",
        type: "text",
        placeholder: "Alex Morgan",
        autocomplete: "name",
        required: true
      },
      {
        id: "email",
        name: "email",
        label: "Email address",
        type: "email",
        placeholder: "alex@example.com",
        autocomplete: "email",
        required: true
      },
      {
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        placeholder: "(555) 123-4567",
        autocomplete: "tel",
        required: false,
        helper: "Expected format: include your country code if outside the US, for example +1 555 123 4567."
      }
    ];

    function Header() {
      return `
        <p class="eyebrow">Support request</p>
        <h1>How can we help?</h1>
        <p class="intro">Share your contact details and our support team will get back to you as soon as possible.</p>
      `;
    }

    function FormField(field) {
      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${field.required ? " *" : ""}</label>
          <input
            id="${field.id}"
            name="${field.name}"
            type="${field.type}"
            placeholder="${field.placeholder}"
            autocomplete="${field.autocomplete}"
            ${field.required ? "required" : ""}
          >
          ${field.helper ? `<span class="helper-text" id="${field.id}-helper">${field.helper}</span>` : ""}
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="support-card" aria-labelledby="support-title">
          ${Header().replace("<h1>", "<h1 id=\"support-title\">")}
          <form action="#" method="post">
            ${fields.map(FormField).join("")}
            <button type="submit">Submit support request</button>
          </form>
        </section>
      `;
    }

    document.getElementById("app").innerHTML = ContactForm();
  </script>
</body>
</html>
